WITH base AS (SELECT *, FLOOR(amount) amount_whole FROM transactions WHERE account_id IN (6, 29, 38)), with_windows AS (SELECT *, AVG(amount) OVER (PARTITION BY account_id ORDER BY amount_whole, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_avg_amount, COUNT(amount) OVER (PARTITION BY account_id ORDER BY amount_whole, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_count_amount, SUM(amount) OVER (PARTITION BY account_id ORDER BY amount_whole, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_sum_amount, NTILE(3) OVER (PARTITION BY DATE_TRUNC('YEAR', txn_time) ORDER BY amount_whole, id) amount_whole_bucket FROM base), enriched AS (SELECT e.*, a.account_type, a.status, a.opened_date FROM with_windows e JOIN accounts a ON e.account_id = a.id WHERE MONTH(a.opened_date) IN (4, 8, 9)), valid AS (SELECT id, txn_time, merchant, is_flagged, running_avg_amount, running_count_amount, running_sum_amount, amount_whole_bucket, account_type, opened_date, COALESCE(status, 'unassigned') status_filled, COALESCE(status, 'NONE') resolved_status FROM enriched WHERE txn_time > TO_TIMESTAMP('2023-08-05 18:00:00') AND merchant IS NOT NULL), filtered AS (SELECT *, running_count_amount - amount_whole_bucket running_count_amount_minus_amount_whole_bucket FROM valid WHERE txn_time > TO_DATE('2023-04-16')), with_windows_transactions AS (SELECT *, SUM(amount_whole_bucket) OVER (PARTITION BY merchant ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_amount_whole_bucket, NTILE(10) OVER w_grp running_count_amount_minus_amount_whole_bucket_bucket, SUM(running_count_amount) OVER w_recent cumulative_running_count_amount FROM filtered WINDOW w_grp AS (PARTITION BY YEAR(opened_date), account_type ORDER BY running_count_amount_minus_amount_whole_bucket, id), w_recent AS (ORDER BY running_count_amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), flagged AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) > INTERVAL 30 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM with_windows_transactions), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT id, txn_time, merchant, is_flagged, running_avg_amount, running_sum_amount, opened_date, resolved_status, running_count_amount_minus_amount_whole_bucket, session_no, AVG(running_count_amount) OVER (PARTITION BY merchant, account_type ORDER BY running_count_amount_minus_amount_whole_bucket_bucket, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_avg_running_count_amount, MAX(running_count_amount) OVER (PARTITION BY merchant, account_type ORDER BY running_count_amount_minus_amount_whole_bucket_bucket, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_max_running_count_amount, SUM(running_count_amount) OVER (PARTITION BY merchant, account_type ORDER BY running_count_amount_minus_amount_whole_bucket_bucket, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_sum_running_count_amount FROM sessionized;
